package com.sun.fortress.nativeHelpers;

import com.sun.fortress.compiler.runtimeValues.FException;
import com.sun.fortress.compiler.runtimeValues.FortressBufferedReader;
import com.sun.fortress.compiler.runtimeValues.FortressBufferedWriter;
import com.sun.fortress.compiler.runtimeValues.Utility;

import java.lang.reflect.Constructor;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;

import java.nio.charset.Charset;

public class fileOps {

    public static FortressBufferedReader jbrOpen(String name) throws FException {
	try {
	    return new FortressBufferedReader(name, new BufferedReader(new InputStreamReader(new FileInputStream(name), Charset.forName("UTF-8"))));
	} catch (FileNotFoundException e) {
	    throw Utility.makeFortressException("fortress.CompilerBuiltin$FileNotFoundException", e);
	}
    }

    public static String jbrAsString(FortressBufferedReader r) {
	return "[buffered reader " + r.toString() + "]";
    }

    public static int jbrRead(FortressBufferedReader r) throws FException {
	return r.read();
    }

    public static String jbrReadLine(FortressBufferedReader r) throws FException {
	return r.readLine();
    }

    public static String jbrReadk(FortressBufferedReader r, int k) throws FException {
	return r.readk(k);
    }

    public static boolean jbrEof(FortressBufferedReader r) {
	return r.eof();
    }

    public static boolean jbrReady(FortressBufferedReader r) throws FException {
	return r.ready();
    }

    public static void jbrClose(FortressBufferedReader r) throws FException {
	r.close();
    }

    public static void jbrWhenUnconsumed(FortressBufferedReader r) throws FException {
	r.whenUnconsumed();
    }

    public static void jbrConsume(FortressBufferedReader r) throws FException {
	r.consume();
    }


    public static FortressBufferedWriter jbwOpen(String name) throws FException {
	try {
	    return new FortressBufferedWriter(name, new BufferedWriter(new OutputStreamWriter(new FileOutputStream(name), Charset.forName("UTF-8"))));
	} catch (FileNotFoundException e) {
	    throw Utility.makeFortressException("fortress.CompilerBuiltin$FileNotFoundException", e);
	}
    }

    /** A writer over standard output, in UTF-8, named "<stdout>". */
    public static FortressBufferedWriter jbwStdOut() {
        return new FortressBufferedWriter("<stdout>", new BufferedWriter(new OutputStreamWriter(System.out, Charset.forName("UTF-8"))));
    }

    /** A writer over standard error, in UTF-8, named "<stderr>". */
    public static FortressBufferedWriter jbwStdErr() {
        return new FortressBufferedWriter("<stderr>", new BufferedWriter(new OutputStreamWriter(System.err, Charset.forName("UTF-8"))));
    }

    public static String jbwAsString(FortressBufferedWriter w) {
        return "[buffered writer " + w.toString() + "]";
    }

    public static void jbwWriteChar(FortressBufferedWriter w, int c) throws FException {
	w.write(c);
    }

    public static void jbwWriteString(FortressBufferedWriter w, String s) throws FException {
	w.write(s);
    }

    public static void jbwNewLine(FortressBufferedWriter w) throws FException {
	w.newLine();
    }

    public static void jbwFlush(FortressBufferedWriter w) throws FException {
	w.flush();
    }

    public static void jbwClose(FortressBufferedWriter w) throws FException {
	w.close();
    }

}

== explorations/compile-ladder/plan-28/PROBES.md:126-132

## Probe 5. The compiled reader against walk's, at the end of a file (rung R), by reading

- Walk's `FileReadStream$readChar` answers the Java `read()`, -1 at the end, and sets `eof` (`interpreter/glue/prim/FileReadStream.java:141-149`). The library depends on the -1: `ReadStream`'s `eofCheckedReadChar` maps it to `char(0)`, and its `characters` generator ends at it (`Library/FileSupport.fss:64-67`, `:113-118`).
- The compiled run time's `FortressBufferedReader.read()`, which `fileOps.jbrRead` answers, returns 0 at the end and sets `eof` (`compiler/runtimeValues/FortressBufferedReader.java:55-70`), for the prelude's `read(): Character = jMakeCharacter(jJavaBufferedReaderRead(self))` (`ProjectFortress/LibraryBuiltin/CompilerBuiltin.fss:1163`).
- So a `FileReadStream` whose `uncheckedReadChar` named `jbrRead` alone would answer 0 at the end, and `characters` would not end. Read after it, `eof` tells the end from a character 0 on both paths: walk calls the same helper through the carrier.
- The other reader operations agree: `readLine` and `readk` answer `""` at the end on both; `ready` and `close` are the Java calls on both; a read after `consume` raises in both, walk's glue a walk error that no `catch` sees ('Performed operation on consumed FileReadStream …', `reviews/io-objects-carrier-2026-11-06.md`, section 2.2, point 8), the helper `IOFailure` ('Performed operation on consumed reader for …', `FortressBufferedReader.java:118-123`).
- microGPT's lines use `FileReadStream(path)`, `readLine()` until it answers `""`, and `close()` (`explorations/run-c4/src/FlatData.fss:69-86`).

