# countbind.py ROOT : counts builtinPrimitive bindings of the one library, comments stripped, the compiler's files left out
import os, re, sys
root = sys.argv[1]
skip = {"CompilerBuiltin.fss", "CompilerLibrary.fss", "CompilerAlgebra.fss", "CompilerSystem.fss"}
def strip(s):
    out, i, depth = [], 0, 0
    while i < len(s):
        if s.startswith("(*", i): depth += 1; i += 2; continue
        if depth and s.startswith("*)", i): depth -= 1; i += 2; continue
        if depth == 0: out.append(s[i])
        i += 1
    return "".join(out)
helper = glue = 0
per = {}
for d in ["Library", "ProjectFortress/LibraryBuiltin"]:
    for f in sorted(os.listdir(os.path.join(root, d))):
        if not f.endswith(".fss") or f in skip: continue
        s = strip(open(os.path.join(root, d, f), encoding="utf-8").read())
        for m in re.finditer(r'builtinPrimitive\s*\(\s*"([^"]*)"', s):
            k = "helper" if m.group(1).startswith("com.sun.fortress.nativeHelpers.") else "glue"
            per.setdefault(f, [0, 0])[0 if k == "helper" else 1] += 1
            if k == "helper": helper += 1
            else: glue += 1
print("helper", helper, "glue", glue, "total", helper + glue)
for f, (h, g) in sorted(per.items()):
    if f in ("File.fss", "Reader.fss", "FortressLibrary.fss", "FortressBuiltin.fss", "Writer.fss"): print(" ", f, "helper", h, "glue", g)
EOF
